package ir.codelighthouse.bazikhooneh;
import android.content.Intent;import android.os.Bundle;import android.view.View;import android.widget.RadioGroup;
public final class LudoMenuActivity extends NavigableActivity{
 @Override protected void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.activity_ludo_menu);findViewById(R.id.ludo_local).setOnClickListener(v->{findViewById(R.id.ludo_local_options).setVisibility(View.VISIBLE);findViewById(R.id.ludo_start_local).setVisibility(View.VISIBLE);});findViewById(R.id.ludo_start_local).setOnClickListener(v->{int id=((RadioGroup)findViewById(R.id.ludo_player_count)).getCheckedRadioButtonId();int count=id==R.id.ludo_three_players?3:id==R.id.ludo_four_players?4:2;startActivity(new Intent(this,LudoActivity.class).putExtra(LudoActivity.EXTRA_MODE,"local").putExtra(LudoActivity.EXTRA_PLAYERS,count));});findViewById(R.id.ludo_bots).setOnClickListener(v->startActivity(new Intent(this,LudoActivity.class).putExtra(LudoActivity.EXTRA_MODE,"bots")));findViewById(R.id.ludo_online).setOnClickListener(v->startActivity(new Intent(this,LudoOnlineLobbyActivity.class)));findViewById(R.id.ludo_guide).setOnClickListener(v->startActivity(new Intent(this,LudoGuideActivity.class)));}
}
